def simulate(frames, refs, algo):
    mem = []
    last = {}
    misses = 0
    for i, x in enumerate(refs):
        if x in mem:
            last[x] = i
            continue
        misses += 1
        if len(mem) == frames:
            if algo == 'fifo':
                mem.pop(0)
            else:
                victim = min(mem, key=lambda p: last[p])
                mem.remove(victim)
        mem.append(x)
        last[x] = i
    return misses

refs = [1, 2, 3, 4, 1, 2, 5, 1, 2, 3, 4, 5]
print(simulate(3, refs, 'fifo'), simulate(3, refs, 'lru'))
